/* Brand theming: selecting a manufacturer repaints every orange token in its colour. */
(function () {
  const BRAND_THEMES = {
    Milwaukee: {
      hex: "#C92A28",
      slug: "milwaukee"
    },
    Ryobi: {
      hex: "#CEDC00",
      slug: "ryobi"
    },
    Ava: {
      hex: "#B7FF00",
      slug: "ava"
    },
    Scheppach: {
      hex: "#035388",
      slug: "scheppach"
    },
    "AL-KO": {
      hex: "#E30613",
      slug: "alko"
    }
  };
  const DEFAULTS = {
    "--rr-orange": "#EB6703",
    "--rr-orange-logo": "#EC6324",
    "--rr-orange-deep": "#C24E00",
    "--rr-orange-bright": "#FF7A1A",
    "--rr-orange-tint": "#FDE4CC",
    "--rr-orange-pale": "#FFF4EA",
    "--fg-on-brand": "#FFFFFF",
    "--fg-brand": "#C24E00",
    "--fg-link": "#C24E00",
    "--shadow-brand": "0 8px 24px rgba(235,103,3,0.28)"
  };
  const rgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
  const hex = c => "#" + c.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")).join("");
  const mix = (a, b, t) => a.map((v, i) => v + (b[i] - v) * t);
  const lum = c => {
    const f = c.map(v => {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2];
  };
  const contrast = (a, b) => {
    const l1 = lum(a),
      l2 = lum(b);
    return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
  };
  function applyBrandTheme(brand) {
    const root = document.documentElement;
    const t = BRAND_THEMES[brand];
    if (!t) {
      Object.entries(DEFAULTS).forEach(([k, v]) => root.style.setProperty(k, v));
      return;
    }
    const base = rgb(t.hex);
    const white = [255, 255, 255],
      black = [0, 0, 0];
    // Text-safe variant: darken until it clears 4.5:1 on white.
    let ink = base,
      step = 0;
    while (contrast(ink, white) < 4.5 && step < 24) {
      step++;
      ink = mix(base, black, step * 0.04);
    }
    const onBrand = contrast(base, white) >= 3.2 ? "#FFFFFF" : "var(--rr-ink)";
    root.style.setProperty("--rr-orange", t.hex);
    root.style.setProperty("--rr-orange-logo", t.hex);
    root.style.setProperty("--rr-orange-deep", hex(mix(base, black, 0.22)));
    root.style.setProperty("--rr-orange-bright", hex(mix(base, white, 0.14)));
    root.style.setProperty("--rr-orange-tint", hex(mix(base, white, 0.80)));
    root.style.setProperty("--rr-orange-pale", hex(mix(base, white, 0.93)));
    root.style.setProperty("--fg-on-brand", onBrand);
    root.style.setProperty("--fg-brand", hex(ink));
    root.style.setProperty("--fg-link", hex(ink));
    root.style.setProperty("--shadow-brand", "0 8px 24px " + `rgba(${base.map(Math.round).join(",")},0.30)`);
  }
  function brandLogo(brand, variant) {
    const t = BRAND_THEMES[brand];
    const v = variant === "light" ? "white" : "dark";
    if (!t) return v === "white" ? "../../assets/logos/retail-repair-wordmark-white.png" : "../../assets/logos/retail-repair-wordmark.png";
    return `../../assets/logos/brand/${t.slug}-${v}.png`;
  }

  // Preload every tinted wordmark so a brand switch repaints in the same frame as the tokens.
  const preloaded = [];
  for (const t of Object.values(BRAND_THEMES)) {
    for (const v of ["white", "dark"]) {
      const im = new Image();
      im.src = `../../assets/logos/brand/${t.slug}-${v}.png`;
      preloaded.push(im);
    }
  }
  window.__rrPreloadedLogos = preloaded;
  window.BRAND_THEMES = BRAND_THEMES;
  window.applyBrandTheme = applyBrandTheme;
  window.brandLogo = brandLogo;
})();
